-- --------------------------------------
-- Container loot: bags and kits whose tooltip states their contents, generated from the client data
-- (AccountAudit lists containers still without item_loot). minCount = maxCount = N picks N entries by weight.
-- Amounts marked GUESS have no source.
-- --------------------------------------
DELETE FROM `item_loot` WHERE `lootGroupId` BETWEEN 1100000000 AND 1100999999;
DELETE FROM `loot_item` WHERE `id` BETWEEN 1100000000 AND 1100999999;
UPDATE `loot_group` SET `parentId` = NULL WHERE `id` BETWEEN 1100000000 AND 1100999999;
DELETE FROM `loot_group` WHERE `id` BETWEEN 1100000000 AND 1100999999;

